    /// <summary>
    /// Spawns a detached relauncher process that waits for this process to
    /// exit (preventing bind-conflict on the control port), then restarts
    /// the app the same way it was started. After spawning, shuts down the
    /// current instance so the relauncher can take over.
    /// </summary>
    private static async Task TriggerRestartAndShutdownAsync(RestartHandoff handoff)
    {
        var pid = Environment.ProcessId;
        var relaunchArgs = BuildRelaunchArgs(pid, handoff.RootPath);
        if (relaunchArgs is null)
        {
            // No restart path; the handoff stays on disk for manual resume.
            DrainSummaryLog.Write(handoff.RootPath, handoff.DrainId, "relaunch",
                "restart-handoff", "relauncher-unavailable");
            return;
        }

        try
        {
            var startInfo = new System.Diagnostics.ProcessStartInfo
            {
                FileName = relaunchArgs.Value.Process,
                Arguments = relaunchArgs.Value.Arguments,
                WorkingDirectory = handoff.RootPath,
                CreateNoWindow = true,
                UseShellExecute = false,
            };
            System.Diagnostics.Process.Start(startInfo);
        }
        catch (Exception ex)
        {
            DrainSummaryLog.Write(handoff.RootPath, handoff.DrainId, "relaunch",
                "restart-handoff", $"relauncher-failed: {ex.Message}");
            return;
        }

        // Give the relauncher a moment to attach, then exit so it can
        // detect our exit and restart the app.
        await Task.Delay(200);
        Environment.Exit(0);
    }

    private static (string Process, string Arguments)? BuildRelaunchArgs(int parentPid, string rootPath)
    {
        // Source checkout: VISUAL_RELAY_SCRIPT_DIR env var points to the
        // tools directory; use dotnet run to recompile + restart.
        var scriptDir = Environment.GetEnvironmentVariable("VISUAL_RELAY_SCRIPT_DIR");
        if (!string.IsNullOrWhiteSpace(scriptDir))
        {
            var relauncherProj = Path.Combine(scriptDir, "tools", "VisualRelay.Relauncher");
            return ("dotnet", $"run --project \"{relauncherProj}\" -- --parent-pid {parentPid} --root-path \"{rootPath}\"");
        }

        // Published install: relauncher binary lives next to the app binary.
        var appPath = Environment.ProcessPath;
        if (!string.IsNullOrWhiteSpace(appPath))
        {
            var appDir = Path.GetDirectoryName(appPath)!;
            var relauncherExe = Path.Combine(appDir, "VisualRelay.Relauncher");
            if (OperatingSystem.IsWindows()) relauncherExe += ".exe";
            if (File.Exists(relauncherExe))
                return (relauncherExe, $"--parent-pid {parentPid} --root-path \"{rootPath}\"");
        }

        return null;
    }

}

